func binaryResponseHeaderValue(headers map[string]string) (bool, bool) {
	found := false
	for k, v := range headers {
		if strings.EqualFold(k, BinaryResponseHeader) {
			found = true
			if strings.EqualFold(v, "true") {
				return true, true
			}
		}
	}
	return false, found
}

