type multipartRequestBody struct {
	Fields     map[string]string
	FileFields map[string]string
}

func encodeMultipartBody(body multipartRequestBody) ([]byte, string, error) {
	var buf bytes.Buffer
	writer := multipart.NewWriter(&buf)
	for fieldName, value := range body.Fields {
		if err := writer.WriteField(fieldName, value); err != nil {
			_ = writer.Close()
			return nil, "", fmt.Errorf("writing multipart field %q: %w", fieldName, err)
		}
	}
	for fieldName, filePath := range body.FileFields {
		file, err := os.Open(filePath)
		if err != nil {
			_ = writer.Close()
			return nil, "", fmt.Errorf("opening multipart file field %q (%q): %w", fieldName, filePath, err)
		}
		h := make(textproto.MIMEHeader)
		h.Set("Content-Disposition", fmt.Sprintf(`form-data; name="%s"; filename="%s"`,
			escapeMultipartQuotes(fieldName), escapeMultipartQuotes(filepath.Base(filePath))))
		h.Set("Content-Type", multipartFileContentType(filePath))
		part, err := writer.CreatePart(h)
		if err != nil {
			_ = file.Close()
			_ = writer.Close()
			return nil, "", fmt.Errorf("creating multipart file field %q (%q): %w", fieldName, filePath, err)
		}
		if _, err := io.Copy(part, file); err != nil {
			_ = file.Close()
			_ = writer.Close()
			return nil, "", fmt.Errorf("copying multipart file field %q (%q): %w", fieldName, filePath, err)
		}
		if err := file.Close(); err != nil {
			_ = writer.Close()
			return nil, "", fmt.Errorf("closing multipart file field %q (%q): %w", fieldName, filePath, err)
		}
	}
	if err := writer.Close(); err != nil {
		return nil, "", fmt.Errorf("finalizing multipart body: %w", err)
	}
	return buf.Bytes(), writer.FormDataContentType(), nil
}

// Needed so whitelist-style upload APIs do not 415 the file part.
func multipartFileContentType(path string) string {
	if ct := mime.TypeByExtension(filepath.Ext(path)); ct != "" {
		return ct
	}
	return "application/octet-stream"
}

func escapeMultipartQuotes(s string) string {
	return strings.NewReplacer("\\", "\\\\", `"`, "\\\"").Replace(s)
}

// isMutatingVerb reports whether the HTTP method writes server state.
// Used by do()'s verify-mode short-circuit to gate dial-out: under
// PRINTING_PRESS_VERIFY=1 (without LIVE_HTTP=1 opt-in), generated
// commands must not actually issue mutating requests, even if a
// handler-level dry-run check was missed.
func isMutatingVerb(method string) bool {
	switch method {
	case "DELETE", "POST", "PUT", "PATCH":
		return true
	}
	return false
}

// verifyShortCircuitEnvelope returns the synthetic JSON body that
// stands in for a real mutating response when do() short-circuits in
// verify mode. The __pp_verify_synthetic__ sentinel is namespace-
// reserved (no real API uses __pp_*) so downstream consumers
// (validate-narrative, agent inspections) can key on one obvious field
// instead of trying to disambiguate common literals like status:"noop".
// method and path are echoed back as diagnostic prose for human/agent
// inspection.
func verifyShortCircuitEnvelope(method, path string) json.RawMessage {
	body, _ := json.Marshal(map[string]any{
		"__pp_verify_synthetic__": true,
		"status":                  "noop",
		"reason":                  "verify_short_circuit",
		"method":                  method,
		"path":                    path,
	})
	return json.RawMessage(body)
}

func sleepContext(ctx context.Context, wait time.Duration) error {
	timer := time.NewTimer(wait)
	defer timer.Stop()
	select {
	case <-timer.C:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// Exhausted 429 retries are a pacing signal, not a command failure. Sleep
// the last Retry-After so the attempt can continue while the operation
// deadline still has time; a non-positive wait falls back to one second
// so Retry-After: 0 cannot tight-loop.
func (c *Client) waitForRateLimitRefill(ctx context.Context, wait time.Duration) error {
	if wait <= 0 {
		wait = time.Second
	}
	fmt.Fprintf(os.Stderr, "rate-limit budget empty, waiting %s for refill\n", wait)
	if err := sleepContext(ctx, wait); err != nil {
		return fmt.Errorf("timed out waiting %s for rate-limit budget to refill: %w", wait, err)
	}
	return nil
}

// One --timeout (or the caller's deadline) covers refill waits, limiter
// pacing, and retry sleeps. A fresh timeout per wait would let a
// persistently 429ing endpoint run indefinitely. The HTTP request keeps
// the caller's ctx so unmarked binary streams can outlive the default
// whole-call budget.
func (c *Client) bindOperationDeadline(ctx context.Context) (context.Context, context.CancelFunc) {
	if ctx == nil {
		ctx = context.Background()
	}
	if _, ok := ctx.Deadline(); ok {
		return ctx, func() {}
	}
	if timeout := c.ConfiguredTimeout(); timeout > 0 {
		return context.WithTimeout(ctx, timeout)
	}
	return ctx, func() {}
}

// do executes an HTTP request. headerOverrides, when non-nil, override global
// RequiredHeaders for this specific request (used for per-endpoint API versioning).
func (c *Client) do(ctx context.Context, method, path string, params map[string]string, body any, headerOverrides map[string]string) (json.RawMessage, int, error) {
	return c.doInternal(ctx, method, path, params, body, headerOverrides, false, false)
}

// doRead is do() minus the verify-mode mutating-verb gate. Used by the
// PostQuery* family for read-only operations that ride a mutating verb on
// the wire (GraphQL queries, JSON-RPC reads, POST-based search endpoints).
// The wire verb is still POST/PUT/PATCH so the server sees a real request,
// but the verify-mode short-circuit does not fire because the operation
// does not mutate remote state.
func (c *Client) doRead(ctx context.Context, method, path string, params map[string]string, body any, headerOverrides map[string]string) (json.RawMessage, int, error) {
	return c.doInternal(ctx, method, path, params, body, headerOverrides, true, false)
}

func (c *Client) doMutation(ctx context.Context, method, path string, params map[string]string, body any, headerOverrides map[string]string) (json.RawMessage, int, error) {
	return c.doInternal(ctx, method, path, params, body, headerOverrides, false, true)
}

// doInternal is the shared implementation behind do(), doRead(), and
// doMutation().
// readOnlyIntent flag is set by doRead() callers (read-only POST/PUT/PATCH
// operations like GraphQL queries) to skip the mutating-verb verify-mode
// gate. Plain do() callers leave it false and get the usual short-circuit.
// mutationIntent extends that gate to GET action endpoints whose wire method
// is not itself a mutating verb.
func (c *Client) doInternal(ctx context.Context, method, path string, params map[string]string, body any, headerOverrides map[string]string, readOnlyIntent bool, mutationIntent bool) (json.RawMessage, int, error) {
	// Verify-mode transport-layer gate. When the verifier (or any consumer
	// that sets PRINTING_PRESS_VERIFY=1) drives a mutating verb or explicit
	// mutation intent without the LIVE_HTTP=1 opt-in, return a synthetic
	// envelope without dialing,
	// minting auth, or touching the cache. The verify pipeline itself
	// sets both env vars in mock mode so its httptest server still sees
	// real requests; every other consumer gets a safe no-op.
	//
	// readOnlyIntent suppresses the gate for read-only operations that
	// happen to ride a mutating verb on the wire (GraphQL queries, JSON-RPC
	// reads, POST-based search endpoints). The handler-level annotation
	// `mcp:read-only: true` drives the codegen choice of doRead() vs do().
	//
	// Placement note: this fires BEFORE URL building, auth header
	// minting, and the success-branch invalidateCache() call below — so
	// no cache invalidation runs (no remote state changed) and no
	// client_credentials mint happens unnecessarily.
	if !readOnlyIntent && (mutationIntent || isMutatingVerb(method)) && cliutil.IsVerifyEnv() && !cliutil.IsVerifyLiveHTTPEnv() {
		return verifyShortCircuitEnvelope(method, path), http.StatusOK, nil
	}
	if err := rejectUnresolvedPathParams(path, nil); err != nil {
		return nil, 0, err
	}
	// Bound waits and retries once. Do not attach this deadline to the
	// HTTP request: unmarked binary transfers drop the whole-call
	// Timeout and must keep streaming after --timeout's default budget.
	opCtx, cancel := c.bindOperationDeadline(ctx)
	defer cancel()
	targetURL := c.BaseURL + path

	var bodyBytes []byte
	var contentType string
	if body != nil {
		if multipartBody, ok := body.(multipartRequestBody); ok {
			if c.DryRun {
				// Do not open FileFields: --dry-run must preview without IO.
				preview := make(map[string]string, len(multipartBody.Fields)+len(multipartBody.FileFields))
				for name, value := range multipartBody.Fields {
					preview[name] = value
				}
				for name, filePath := range multipartBody.FileFields {
					preview[name] = "@" + filePath
				}
				b, err := json.Marshal(preview)
				if err != nil {
					return nil, 0, fmt.Errorf("marshaling multipart dry-run preview: %w", err)
				}
				bodyBytes = b
				contentType = "multipart/form-data"
			} else {
				b, ct, err := encodeMultipartBody(multipartBody)
				if err != nil {
					return nil, 0, err
				}
				bodyBytes = b
				contentType = ct
			}
		} else {
			b, err := json.Marshal(body)
			if err != nil {
				return nil, 0, fmt.Errorf("marshaling body: %w", err)
			}
			bodyBytes = b
			contentType = "application/json"
		}
	}

	// Resolve auth material before the dry-run branch so --dry-run can preview
	// exactly what would be sent. Uses only cached credentials; a token that
	// requires a network refresh will be re-fetched on the live request path,
	// not during dry-run.
	authHeader, err := c.authHeader(ctx)
	if err != nil {
		return nil, 0, err
	}

	// Build the request for dry-run display or actual execution
	if c.DryRun {
		return c.dryRun(method, targetURL, path, params, bodyBytes, headerOverrides, authHeader)
	}

	maxRetries := clientMaxRetries()
	// Retry only operations that are safe to replay after an ambiguous
	// transport failure or server error; a write may already have committed
	// remotely even when its wire method is GET.
	canRetryAmbiguousFailure := readOnlyIntent || (!mutationIntent && platform.CanRetryRequest(method, requestIdempotencyKey(c.Config, headerOverrides)))
	endpointClass := safeEndpointClass(method, path)
	retryPolicy, err := c.platformRetryPolicy(endpointClass)
	if err != nil {
		return nil, 0, err
	}
	if retryPolicy.MaxAttempts > 0 && maxRetries > retryPolicy.MaxAttempts-1 {
		maxRetries = retryPolicy.MaxAttempts - 1
	}
	retryStarted := time.Now()
	retryWithinBudget := func(wait time.Duration) bool {
		return retryPolicy.RetryBudget > 0 && time.Since(retryStarted)+wait <= retryPolicy.RetryBudget
	}
	var lastErr error

	for attempt := 0; ; attempt++ {
		if err := c.waitForPlatformBudget(opCtx, endpointClass); err != nil {
			return nil, 0, err
		}
		// Proactive rate limiting — wait before sending
		adaptiveStarted := time.Now()
		if err := c.limiter.Wait(opCtx); err != nil {
			return nil, 0, err
		}
		if c.platformSession != nil {
			c.platformSession.RecordRateLimitWait(time.Since(adaptiveStarted))
		}
		var bodyReader io.Reader
		if bodyBytes != nil {
			bodyReader = strings.NewReader(string(bodyBytes))
		}

		req, err := http.NewRequestWithContext(ctx, method, targetURL, bodyReader)
		if err != nil {
			return nil, 0, fmt.Errorf("creating request: %w", err)
		}
		if bodyBytes != nil {
			req.Header.Set("Content-Type", contentType)
		}

		if params != nil {
			q := req.URL.Query()
			for k, v := range params {
				if v != "" || method != "GET" {
					q.Set(k, v)
				}
			}
			req.URL.RawQuery = q.Encode()
		}

		if authHeader != "" {
			req.Header.Set("X-API-Key", authHeader)
		}
		req.Header.Set("X-Api-Version", "2026-04-01")
		if c.Config != nil {
			for k, v := range c.Config.Headers {
				req.Header.Set(k, v)
			}
		}
		// Per-endpoint header overrides (e.g., different API version per resource)
		for k, v := range headerOverrides {
			req.Header.Set(k, v)
		}
		binaryResponse := strings.EqualFold(req.Header.Get(BinaryResponseHeader), "true")
		if binaryResponse {
			req.Header.Del(BinaryResponseHeader)
		}
		htmlResponse := strings.EqualFold(req.Header.Get(HTMLResponseHeader), "true")
		if htmlResponse {
			req.Header.Del(HTMLResponseHeader)
		}
		if req.Header.Get("User-Agent") == "" {
			if ua := os.Getenv("PRINTING_PRESS_GOLDEN_USER_AGENT"); ua != "" {
				req.Header.Set("User-Agent", ua)
			} else {
				req.Header.Set("User-Agent", "printing-press-golden-pp-cli/2026.04")
			}
		}
		// Go's net/http omits Accept by default; browsers, curl, and other
		// stdlibs always send it. Fingerprint-checking WAFs (Imperva, Akamai,
		// Cloudflare bot-mode, DataDome) flag the absence as a bot signal
		// and answer with empty-body 5xx, 403, or a challenge redirect
		// depending on vendor and rule tier. The value is application/json
		// rather than */* because strict-JSON APIs (Zendesk, Atlassian REST,
		// Salesforce) return 415 on anything that isn't literally
		// application/json; specs that need a different content type
		// (vendor mediatypes, XML, HTML) declare it via RequiredHeaders or
		// per-endpoint headerOverrides, both of which run before this
		// if-empty default.
		if req.Header.Get("Accept") == "" {
			if binaryResponse {
				req.Header.Set("Accept", "*/*")
			} else {
				req.Header.Set("Accept", "application/json")
			}
		}

		if c.platformSession != nil {
			c.platformSession.RecordRateLimitRequest()
		}
		httpClient := c.HTTPClient
		if binaryResponse && !c.timeoutExplicit {
			httpClient = StreamingHTTPClient(c.HTTPClient, c.ConfiguredTimeout())
		}
		resp, err := httpClient.Do(req)
		if err != nil {
			if ctxErr := ctx.Err(); ctxErr != nil {
				return nil, 0, ctxErr
			}
			lastErr = fmt.Errorf("%s %s: %w", method, c.displayURL(path, authHeader), c.maskError(err, authHeader))
			// Transient network failure (connection reset, DNS blip, request
			// timeout). Back off before retrying — same exponential schedule as
			// the 5xx path below — so a brief outage does not burn every attempt
			// in a tight loop. ctx cancellation breaks out of the wait at once.
			if attempt < maxRetries && canRetryAmbiguousFailure && !isPermanentDNSError(err) {
				wait := time.Duration(math.Pow(2, float64(attempt))) * time.Second
				if !retryWithinBudget(wait) {
					return nil, 0, lastErr
				}
				fmt.Fprintf(os.Stderr, "network error (%v), retrying in %s (attempt %d/%d)\n", c.maskError(err, authHeader), wait, attempt+1, maxRetries)
				if serr := sleepContext(opCtx, wait); serr != nil {
					return nil, 0, serr
				}
				continue
			}
			return nil, 0, lastErr
		}

		respBody, err := io.ReadAll(resp.Body)
		_ = resp.Body.Close()
		if err != nil {
			return nil, 0, fmt.Errorf("reading response: %w", err)
		}

		// Pace to the server-advertised budget when it ships rate-limit
		// headers (every response, success or 429). This takes priority over
		// the blind adaptive ramp/halve, which only governs header-less
		// servers and the very first request of a session.
		if remaining, resetAt, ok := cliutil.ParseRateLimitHeaders(resp.Header); ok {
			c.limiter.ObserveHeaders(remaining, resetAt)
		}

		// Success
		if resp.StatusCode < 400 {
			c.limiter.OnSuccess()
			if !readOnlyIntent && (mutationIntent || method != http.MethodGet) && !c.DryRun {
				c.invalidateCacheAfterMutation(path)
			}
			// Non-textual bodies (PDF, zip, image, octet-stream) must not be
			// run through the JSON sanitizer or returned as raw json.RawMessage
			// — return a self-describing base64 envelope instead. Textual and
			// JSON responses fall through to the unchanged path.
			if isBinaryResponseContentType(resp.Header.Get("Content-Type")) {
				env, encErr := wrapBinaryResponse(resp.Header.Get("Content-Type"), respBody)
				if encErr != nil {
					return nil, 0, encErr
				}
				return env, resp.StatusCode, nil
			}
			if !htmlResponse {
				if summary, ok := summarizeHTMLDocument(respBody); ok {
					return nil, resp.StatusCode, fmt.Errorf("%s %s: expected JSON, API returned HTML instead of JSON: %s", method, c.displayURL(path, authHeader), summary)
				}
			}
			return json.RawMessage(sanitizeJSONResponse(respBody)), resp.StatusCode, nil
		}

		if !binaryResponse {
			respBody = sanitizeJSONResponse(respBody)
		}

		apiErr := &APIError{
			Method:     method,
			Path:       c.displayURL(path, authHeader),
			StatusCode: resp.StatusCode,
			Body:       c.maskCredentialText(truncateBody(respBody), authHeader),
		}

		// Rate limited: classify before provider decoding. The server-driven
		// 429 / Retry-After retry policy is unchanged (maxRetries, RetryBudget,
		// RetryAfterDelay). Unsafe-to-replay writes still return the shared
		// typed error. After that policy is exhausted, wait for the local
		// politeness budget to refill — bounded by ctx / --timeout — instead
		// of failing the command while time remains.
		if resp.StatusCode == http.StatusTooManyRequests {
			c.limiter.OnRateLimit()
			wait := platform.RetryAfterDelay(resp.Header.Get("Retry-After"), attempt, time.Now().UTC(), nil)
			if attempt < maxRetries && canRetryAmbiguousFailure && retryWithinBudget(wait) {
				if c.platformSession != nil {
					c.platformSession.RecordRateLimitRetry(wait)
				}
				fmt.Fprintf(os.Stderr, "rate limited, waiting %s (attempt %d/%d, rate adjusted to %.1f req/s)\n", wait, attempt+1, maxRetries, c.limiter.Rate())
				if err := sleepContext(opCtx, wait); err != nil {
					return nil, 0, err
				}
				lastErr = apiErr
				continue
			}
			if canRetryAmbiguousFailure && maxRetries > 0 && attempt >= maxRetries {
				if c.platformSession != nil {
					c.platformSession.RecordRateLimitWait(wait)
				}
				if err := c.waitForRateLimitRefill(opCtx, wait); err != nil {
					return nil, 0, err
				}
				lastErr = apiErr
				continue
			}
			requestID := resp.Header.Get("X-Request-ID")
			if requestID == "" {
				requestID = resp.Header.Get("Request-ID")
			}
			if c.platformSession != nil {
				c.platformSession.RecordRateLimitExhausted()
			}
			return nil, resp.StatusCode, &platform.RateLimitedError{
				EndpointClass: endpointClass, Attempts: attempt + 1,
				RetryAfter: wait, RequestID: requestID,
				Cause: &cliutil.RateLimitError{
					URL:        apiErr.Path,
					RetryAfter: wait,
					Body:       apiErr.Body,
					Cause:      apiErr,
				},
			}
		}

		// Server error - retry with backoff
		if resp.StatusCode >= 500 && attempt < maxRetries && canRetryAmbiguousFailure {
			wait := time.Duration(math.Pow(2, float64(attempt))) * time.Second
			if !retryWithinBudget(wait) {
				return nil, resp.StatusCode, apiErr
			}
			fmt.Fprintf(os.Stderr, "server error %d, retrying in %s (attempt %d/%d)\n", resp.StatusCode, wait, attempt+1, maxRetries)
			if err := sleepContext(opCtx, wait); err != nil {
				return nil, 0, err
			}
			lastErr = apiErr
			continue
		}

		// Client error or retries exhausted - return the error
		return nil, resp.StatusCode, apiErr
	}
}

func safeEndpointClass(method, path string) string {
	path = strings.TrimSpace(path)
	if parsed, err := url.Parse(path); err == nil && parsed.IsAbs() {
		path = parsed.EscapedPath()
	}
	segments := strings.Split(strings.Trim(path, "/"), "/")
	for index, segment := range segments {
		if index >= 2 {
			segments = segments[:2]
			break
		}
		if _, err := strconv.ParseInt(segment, 10, 64); err == nil || len(segment) > 48 {
			segments[index] = ":id"
		}
	}
	return strings.ToUpper(method) + " /" + strings.Join(segments, "/")
}

// dryRun prints the outgoing request exactly as the live path would send it,
// using the auth material already resolved in `do()`. Never triggers a network
// call — the caller is responsible for passing cached auth material only.
func (c *Client) dryRun(method, targetURL, path string, params map[string]string, body []byte, headerOverrides map[string]string, authHeader string) (json.RawMessage, int, error) {
	fmt.Fprintf(os.Stderr, "%s %s\n", method, c.displayURL(targetURL, authHeader))
	queryPrinted := false
	if params != nil {
		keys := make([]string, 0, len(params))
		for k := range params {
			if params[k] != "" || method != "GET" {
				keys = append(keys, k)
			}
		}
		sort.Strings(keys)
		for _, k := range keys {
			sep := "?"
			if queryPrinted {
				sep = "&"
			}
			fmt.Fprintf(os.Stderr, "  %s%s=%s\n", sep, k, c.maskCredentialText(params[k], authHeader))
			queryPrinted = true
		}
	}
	_ = queryPrinted
	if body != nil {
		var pretty json.RawMessage
		if json.Unmarshal(body, &pretty) == nil {
			enc := json.NewEncoder(os.Stderr)
			enc.SetIndent("  ", "  ")
			fmt.Fprintf(os.Stderr, "  Body:\n")
			enc.Encode(pretty)
		}
	}
	if authHeader != "" {
		fmt.Fprintf(os.Stderr, "  %s: %s\n", "X-API-Key", maskToken(authHeader))
	}
	fmt.Fprintf(os.Stderr, "\n(dry run - no request sent)\n")
	return json.RawMessage(`{"dry_run": true}`), 0, nil
}

func (c *Client) ConfiguredTimeout() time.Duration {
	if c.HTTPClient != nil && c.HTTPClient.Timeout > 0 {
		return c.HTTPClient.Timeout
	}
	return 60 * time.Second
}

func (c *Client) authHeader(ctx context.Context) (string, error) {
	if c.Config == nil {
		return "", nil
	}
	authHeader := c.Config.AuthHeader()
	if authHeader == "" && c.Config.HasCredentialRefusals() {
		return "", c.Config.CredentialRefusalError()
	}
	if authHeaderLooksLikePlaceholderCredential(authHeader) {
		return "", authPlaceholderCredentialError(c.Config)
	}
	return authHeader, nil
}

func authHeaderLooksLikePlaceholderCredential(header string) bool {
	if scheme, encoded, ok := strings.Cut(strings.TrimSpace(header), " "); ok && strings.EqualFold(scheme, "Basic") {
		encoded = strings.TrimSpace(encoded)
		decoded, err := base64.StdEncoding.DecodeString(encoded)
		if err == nil && authHeaderLooksLikePlaceholderCredential(string(decoded)) {
			return true
		}
	}
	if !strings.Contains(header, "<") && !strings.Contains(header, "YOUR_TOKEN_HERE") && !strings.Contains(header, "your-token") && !strings.Contains(header, "your-key") {
		return false
	}
	for _, field := range strings.Fields(header) {
		field = strings.Trim(field, `"'`)
		if idx := strings.LastIndex(field, "="); idx >= 0 {
			field = field[idx+1:]
		}
		if idx := strings.Index(field, ":"); idx >= 0 {
			if looksLikeCredentialPlaceholder(field[:idx]) || looksLikeCredentialPlaceholder(field[idx+1:]) {
				return true
			}
		}
		if looksLikeCredentialPlaceholder(field) {
			return true
		}
	}
	return looksLikeCredentialPlaceholder(header)
}

func looksLikeCredentialPlaceholder(value string) bool {
	value = strings.Trim(strings.TrimSpace(value), `"'`)
	switch value {
	case "<your-token>", "<your-key>", "<paste-your-key>", "YOUR_TOKEN_HERE", "your-token-here":
		return true
	}
	if len(value) < 3 || value[0] != '<' || value[len(value)-1] != '>' {
		return false
	}
	for _, r := range value[1 : len(value)-1] {
		if r != '_' && (r < 'A' || r > 'Z') {
			return false
		}
	}
	return true
}

func authPlaceholderCredentialError(cfg *config.Config) error {
	return authPlaceholderCredentialErrorWithSetup(cfg, "export PRINTING_PRESS_GOLDEN_API_KEY=<your-token-here> or echo \"$TOKEN\" | printing-press-golden-pp-cli auth set-token")
}

func authPlaceholderCredentialErrorWithSetup(cfg *config.Config, setup string) error {
	location := "config file"
	if cfg != nil && cfg.Path != "" {
		location = cfg.Path
	}
	return fmt.Errorf("%w configured in %s; set a real token with: %s", ErrPlaceholderCredential, location, setup)
}

// binaryResponseEnvelope wraps a non-textual success body so it survives the
// json.RawMessage contract every consumer (CLI output, --json, MCP tools)
// depends on. Without it, raw bytes (PDF, zip, image) are corrupted by
// sanitizeJSONResponse and emitted as invalid JSON. The _pp_binary
// discriminator lets callers and agents detect and base64-decode the payload.
type binaryResponseEnvelope struct {
	PPBinary    bool   `json:"_pp_binary"`
	ContentType string `json:"content_type"`
	Encoding    string `json:"encoding"`
	Bytes       int    `json:"bytes"`
	Data        string `json:"data"`
}

// isBinaryResponseContentType reports whether a successful response with this
// Content-Type must be base64-wrapped instead of treated as text/JSON. It is
// deliberately narrow: JSON, */*, XML, and every text/* type (including
// text/html, so response_format:html CLIs are untouched) pass through
// unchanged. Only genuinely binary payloads are wrapped.
func isBinaryResponseContentType(ct string) bool {
	mt := strings.ToLower(strings.TrimSpace(ct))
	if i := strings.IndexByte(mt, ';'); i >= 0 {
		mt = strings.TrimSpace(mt[:i])
	}
	if mt == "" {
		return false
	}
	switch {
	case mt == "application/json", mt == "text/json", mt == "*/*":
		return false
	case strings.HasPrefix(mt, "text/"):
		return false
	case strings.HasSuffix(mt, "+json"), strings.HasSuffix(mt, "+xml"):
		return false
	case mt == "application/xml", mt == "application/xhtml+xml":
		return false
	case mt == "application/javascript", mt == "application/ecmascript",
		mt == "application/x-www-form-urlencoded", mt == "application/graphql":
		return false
	}
	return true
}

// wrapBinaryResponse marshals body into a self-describing base64 envelope.
func wrapBinaryResponse(ct string, body []byte) (json.RawMessage, error) {
	out, err := json.Marshal(binaryResponseEnvelope{
		PPBinary:    true,
		ContentType: ct,
		Encoding:    "base64",
		Bytes:       len(body),
		Data:        base64.StdEncoding.EncodeToString(body),
	})
	if err != nil {
		return nil, fmt.Errorf("encoding binary response: %w", err)
	}
	return json.RawMessage(out), nil
}

// sanitizeJSONResponse strips known JSONP/XSSI prefixes and UTF-8 BOM from
// response bodies so that downstream JSON parsing succeeds. For clean JSON
// responses these checks are no-ops.
func sanitizeJSONResponse(body []byte) []byte {
	// UTF-8 BOM
	body = bytes.TrimPrefix(body, []byte("\xEF\xBB\xBF"))

	// JSONP/XSSI prefixes, ordered longest-first where prefixes overlap
	prefixes := [][]byte{
		[]byte(")]}'\n"),
		[]byte(")]}'"),
		[]byte("{}&&"),
		[]byte("for(;;);"),
		[]byte("while(1);"),
	}
	for _, p := range prefixes {
		if bytes.HasPrefix(body, p) {
			body = bytes.TrimPrefix(body, p)
			body = bytes.TrimLeft(body, " \t\r\n")
			break
		}
	}
	return body
}

// maskToken returns a fixed placeholder for a non-empty token.
func maskToken(token string) string {
	if token == "" {
		return ""
	}
	return "****"
}

type maskedError struct {
	msg string
}

func (e maskedError) Error() string {
	return e.msg
}

func (c *Client) displayURL(rawURL string, extraCredentials ...string) string {
	return c.maskCredentialText(rawURL, extraCredentials...)
}

func (c *Client) maskError(err error, extraCredentials ...string) error {
	if err == nil {
		return nil
	}
	raw := err.Error()
	msg := c.maskCredentialText(raw, extraCredentials...)
	if msg == raw {
		return err
	}
	return maskedError{msg: msg}
}

func (c *Client) maskCredentialText(text string, extraCredentials ...string) string {
	if text == "" {
		return text
	}
	type credentialMask struct {
		needle      string
		replacement string
	}
	var masks []credentialMask
	seen := map[string]struct{}{}
	addValue := func(value string) {
		value = strings.TrimSpace(value)
		if value == "" {
			return
		}
		replacement := maskToken(value)
		addMask := func(needle string) {
			if needle == "" {
				return
			}
			if _, ok := seen[needle]; ok {
				return
			}
			seen[needle] = struct{}{}
			masks = append(masks, credentialMask{needle: needle, replacement: replacement})
		}
		addMask(value)
		if escaped := url.QueryEscape(value); escaped != value {
			addMask(escaped)
		}
		if escaped := url.PathEscape(value); escaped != value {
			addMask(escaped)
		}
	}
	addCredential := func(value string) {
		value = strings.TrimSpace(value)
		addValue(value)
		if _, token, ok := strings.Cut(value, " "); ok {
			addValue(token)
		}
	}
	for _, value := range extraCredentials {
		addCredential(value)
	}
	if c != nil && c.Config != nil {
		addCredential(c.Config.AuthHeaderVal)
		addCredential(c.Config.AuthHeader())
		addCredential(c.Config.AccessToken)
		addCredential(c.Config.RefreshToken)
		addCredential(c.Config.ClientSecret)
		addCredential(c.Config.PrintingPressGoldenApiKey)
	}
	sort.SliceStable(masks, func(i, j int) bool {
		return len(masks[i].needle) > len(masks[j].needle)
	})
	masked := text
	for _, mask := range masks {
		masked = strings.ReplaceAll(masked, mask.needle, mask.replacement)
	}
	return masked
}

func truncateBody(b []byte) string {
	if summary, ok := collapseHTMLErrorBody(b); ok {
		return summary
	}
	if len(b) <= maxErrorBodyBytes {
		return string(b)
	}
	return strings.ToValidUTF8(string(b[:maxErrorBodyBytes]), "") + "..."
}

func collapseHTMLErrorBody(b []byte) (string, bool) {
	return summarizeHTMLBody(b, "HTML error page")
}

func summarizeHTMLDocument(b []byte) (string, bool) {
	return summarizeHTMLBody(b, "HTML document")
}

func summarizeHTMLBody(b []byte, kind string) (string, bool) {
	scanBytes := b
	if len(scanBytes) > maxErrorBodyBytes {
		scanBytes = scanBytes[:maxErrorBodyBytes]
	}
	body := strings.ToValidUTF8(string(scanBytes), "")
	trimmed := strings.TrimSpace(body)
	if trimmed == "" || !looksLikeHTMLBody(trimmed) {
		return "", false
	}

	summary := fmt.Sprintf("%s (%d bytes)", kind, len(b))
	if title := extractHTMLTitle(trimmed); title != "" {
		summary += ": " + truncateRunes(title, 160)
	}
	return summary, true
}

func looksLikeHTMLBody(body string) bool {
	lower := strings.ToLower(body)
	if strings.HasPrefix(lower, "<!doctype html") || strings.HasPrefix(lower, "<html") {
		return true
	}
	sample := lower
	if len(sample) > 2048 {
		sample = sample[:2048]
	}
	return strings.HasPrefix(sample, "<") && (strings.Contains(sample, "<body") || strings.Contains(sample, "<head") || strings.Contains(sample, "<title") || strings.Contains(sample, "<script"))
}

func extractHTMLTitle(body string) string {
	pos := 0
	ignoredBlock := ""
	for pos < len(body) {
		tagStartRel := strings.IndexByte(body[pos:], '<')
		if tagStartRel < 0 {
			return ""
		}
		tagStart := pos + tagStartRel
		tagEnd := htmlTagEnd(body, tagStart)
		if tagEnd < 0 {
			return ""
		}
		tagName, closing := htmlTagName(body[tagStart+1 : tagEnd])
		pos = tagEnd + 1
		if tagName == "" {
			continue
		}
		if ignoredBlock != "" {
			if closing && tagName == ignoredBlock {
				ignoredBlock = ""
			}
			continue
		}
		if closing {
			continue
		}
		if tagName == "script" || tagName == "style" {
			ignoredBlock = tagName
			continue
		}
		if tagName != "title" {
			continue
		}
		titleEnd := findHTMLCloseTag(body, pos, "title")
		if titleEnd < 0 {
			return ""
		}
		title := stripHTMLTags(body[pos:titleEnd])
		return strings.Join(strings.Fields(stripControlCharacters(html.UnescapeString(title))), " ")
	}
	return ""
}

func findHTMLCloseTag(body string, from int, tag string) int {
	pos := from
	for pos < len(body) {
		tagStartRel := strings.IndexByte(body[pos:], '<')
		if tagStartRel < 0 {
			return -1
		}
		tagStart := pos + tagStartRel
		tagEnd := htmlTagEnd(body, tagStart)
		if tagEnd < 0 {
			return -1
		}
		tagName, closing := htmlTagName(body[tagStart+1 : tagEnd])
		if closing && tagName == tag {
			return tagStart
		}
		pos = tagEnd + 1
	}
	return -1
}

func htmlTagEnd(body string, start int) int {
	end := strings.IndexByte(body[start:], '>')
	if end < 0 {
		return -1
	}
	return start + end
}

func htmlTagName(raw string) (string, bool) {
	raw = strings.TrimLeftFunc(raw, isHTMLSpace)
	closing := false
	if strings.HasPrefix(raw, "/") {
		closing = true
		raw = strings.TrimLeftFunc(raw[1:], isHTMLSpace)
	}
	if raw == "" || strings.HasPrefix(raw, "!") || strings.HasPrefix(raw, "?") {
		return "", closing
	}
	end := 0
	for end < len(raw) && isHTMLTagNameByte(raw[end]) {
		end++
	}
	if end == 0 {
		return "", closing
	}
	return strings.ToLower(raw[:end]), closing
}

func isHTMLTagNameByte(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') || b == '-' || b == ':'
}

func isHTMLSpace(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\f'
}

func stripHTMLTags(body string) string {
	var out strings.Builder
	inTag := false
	for _, r := range body {
		switch r {
		case '<':
			inTag = true
			out.WriteByte(' ')
		case '>':
			inTag = false
		default:
			if !inTag {
				out.WriteRune(r)
			}
		}
	}
	return out.String()
}

func stripControlCharacters(text string) string {
	return strings.Map(func(r rune) rune {
		if r == '\t' || r == '\n' || r == '\r' {
			return ' '
		}
		if unicode.Is(unicode.Zl, r) || unicode.Is(unicode.Zp, r) {
			return ' '
		}
		if unicode.Is(unicode.Cf, r) {
			return -1
		}
		if unicode.IsControl(r) {
			return -1
		}
		return r
	}, text)
}

func truncateRunes(text string, maxRunes int) string {
	if maxRunes <= 0 {
		return text
	}
	runes := []rune(text)
	if len(runes) <= maxRunes {
		return text
	}
	return string(runes[:maxRunes]) + "..."
}

func clientMaxRetries() int {
	if cliutil.IsVerifyEnv() || cliutil.IsDogfoodEnv() {
		return 0
	}
	return 3
}

// isPermanentDNSError identifies known resolver failures that cannot succeed
// by replaying the request. Timeouts, explicitly temporary failures, and
// otherwise unclassified DNS errors remain retryable.
func isPermanentDNSError(err error) bool {
	var dnsErr *net.DNSError
	if !errors.As(err, &dnsErr) {
		return false
	}
	if dnsErr.IsNotFound {
		return true
	}
	if dnsErr.IsTimeout || dnsErr.IsTemporary {
		return false
	}
	reason := strings.ToLower(strings.TrimSpace(dnsErr.Err))
	// The generic "server misbehaving" text is also used for transient
	// SERVFAIL responses, so only explicit refusal text is terminal here.
	return strings.Contains(reason, "refused")
}
